const items = input.all();
const stats = {};

let total = 0;
let resolvedCount = 0;
let escalatedCount = 0;
let totalTurns = 0;
let csatSum = 0;
let csatCount = 0;

items.forEach(item => {
  const row = item.json;
  total++;
  if (row.outcome === 'resolved') resolvedCount++;
  if (row.outcome === 'escalated') escalatedCount++;
  totalTurns += (row.turn_count || 0);
  if (row.satisfaction != null) {
    csatSum += parseFloat(row.satisfaction);
    csatCount++;
  }
});

const resolutionRate = total > 0 ? (resolvedCount / total) * 100 : 0;
const escalationRate = total > 0 ? (escalatedCount / total) * 100 : 0;
const avgTurns = total > 0 ? (totalTurns / total) : 0;
const avgCsat = csatCount > 0 ? (csatSum / csatCount) : 0;

return [{
  json: {
    total_sessions: total,
    resolution_rate_percent: resolutionRate.toFixed(1),
    escalation_rate_percent: escalationRate.toFixed(1),
    avg_turns: avgTurns.toFixed(1),
    avg_csat: avgCsat.toFixed(2),
    date: new Date().toISOString().split('T')[0]
  }
}];

